from pathlib import Path
from lxml import html,etree
import fitz
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[3];D=HERE/'.proof';D.mkdir(exist_ok=True)
doc=fitz.open(ROOT/'mock-exams/exams/2025Honshi/1/source/problem.pdf')
css='''*{box-sizing:border-box}body{margin:0;padding:16px;font:16px/1.9 sans-serif;color:#222;background:#eee}.page{max-width:850px;margin:0 auto 28px;background:#fff;padding:24px}.exam-section-heading{font-size:1.3rem;font-weight:bold}.exam-question{font-weight:600}p{margin:.7em 0}.blank{display:inline-block;border:1px solid #444;min-width:2em;text-align:center;padding:0 .2em;line-height:1.45;white-space:nowrap}.table-wrap{overflow-x:auto;margin:1.2em 0}table{border-collapse:collapse;min-width:100%;width:max-content}th,td{border:1px solid #888;padding:6px 10px;max-width:620px}caption{caption-side:top;font-weight:600;text-align:left;white-space:normal}fieldset{margin:1.2em 0;padding:12px;min-width:0}legend{font-weight:600}.choice-grid{display:grid;gap:8px}.option{display:flex;gap:12px;align-items:baseline}.option-number{flex-shrink:0}.option-text{overflow-wrap:anywhere}.figure-row{display:flex;align-items:flex-start;gap:16px}.figure-row>figure{flex:1;min-width:0}figure{margin:20px 0}img{width:auto;max-width:100%;height:auto;display:block;margin:auto}figcaption{font-size:.9rem;margin-top:8px}.rules,.mail-body{border:1px solid #888;padding:12px}.mail-body p{margin:3px 0}.code{font-family:monospace;font-size:14px;line-height:1.9;overflow-wrap:anywhere}.code-row{display:flex;gap:10px}.ln{width:3em;flex-shrink:0}.src{padding-left:calc(var(--depth) * 1.5em);white-space:pre-wrap;min-width:0}.source-box{border-left:1px dashed #777;border-right:1px dashed #777}.source-box-first{border-top:1px dashed #777}.source-box-last{border-bottom:1px dashed #777}.program{border:1px solid #888;padding:12px}.conditions dd{margin-bottom:10px}.dialogue p{margin-bottom:.7em}@media(max-width:600px){body{padding:8px}.page{padding:14px}.figure-row{flex-direction:column}.figure-row>figure{width:100%}.table-wrap{max-width:100%}th,td{padding:5px 8px;max-width:260px}.code{font-size:12px}.program{padding:8px}.code-row{gap:4px}.src{padding-left:calc(var(--depth) * .8em)}}'''
for sid in ['q1','q2a','q2b','q3','q4']:
 t=html.fragment_fromstring((HERE/(sid+'.html')).read_text(),create_parent='div')
 for n,f in enumerate(t.xpath('.//figure[@class="past-diagram"]')):
  page=int(f.get('data-pdf-page'));clip=fitz.Rect(list(map(float,f.get('data-pdf-clip').split())));name=f'{sid}-{n}.png';doc[page-1].get_pixmap(matrix=fitz.Matrix(1.7,1.7),clip=clip).save(D/name);f.insert(0,etree.Element('img',src=name,alt=f.xpath('string(./figcaption)')))
 for r in t.xpath('.//*[@data-depth]'):r.set('style','--depth:'+r.get('data-depth'))
 (D/(sid+'.html')).write_text('<!doctype html><html lang="ja"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><style>'+css+'</style><body>'+''.join(etree.tostring(e,encoding='unicode',method='html') for e in t)+'</body></html>')
print('Proof only:',D)
